/* Example: styling an element to be scrollable */
body {
  height: 100vh;
  overflow-y: scroll;
}

/* Example: styling a section */
.section {
    background-color: lightblue;
    height: 200px;
    margin: 20px;
}

/* Similar: another keyframes animation */
@keyframes slideIn {
    from { transform: translateX(-100%); }
    to { transform: translateX(0); }
}

/* Applying an animation to an element */
.element {
    animation: fadeIn 2s;
}

/* Example: connecting an animation to scroll */
.element {
    animation: fadeIn 1s ease;
    animation-timeline: scroll();
}

/* Example: animation-range controls scroll range */
.element {
    animation: fadeIn 1s ease;
    animation-range: cover 0% 100%;
}

/* Example of view() timeline usage */
.viewport-box {
    animation: fadeIn 2s ease;
    animation-timeline: view();
}

/* Example: animation-range with view() timeline */
.element {
    animation: fadeIn 1s ease;
    animation-timeline: view();
    animation-range: entry 10% exit 90%;
}

/* Example of multiple animations */
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.third-section {
    animation: fadeIn 1s ease;
    animation-timeline: scroll();
    animation-range: 0% 50%;
}
